// Sierpinski Bits - bitwise fractal (x AND y), seam-free. Parametric (u,v), animated.
//
// The cells where (x AND y) == 0 draw a Sierpinski gasket; every other cell
// lies in a triangular hole whose size is the highest bit of (x AND y). Holes
// are colored by size and a brightness wave runs through the scales.
// SEAM-FREE: 2^BITS cells per turn, indices wrapped -> no jump at u = 0/1 or
// v = 0/1. For surfaces glued with a twist (Klein bottle, Moebius band) set
// MIRROR_V (or MIRROR_U) to 1.0. Stays seam-free with any pan, zoom 1, 1/2...
// Dock colors: u_col1 = gasket lines, u_col2 = deep tone of the big holes.

const int   BITS      = 8;     // 2^BITS cells per turn             [5 .. 10]
const float TILES_V   = 1.0;   // gaskets around v: 1, 2, 4 (integer)
const float WAVE      = 0.35;  // speed of the wave through the scales (0 = still)
const float DRIFT     = 0.0;   // slow slide along u (turns per second)
const float RAINBOW   = 0.8;   // 0 = dock colors only, 1 = spectrum per scale
const float NESTING   = 0.7;   // shading of the holes nested in bigger ones [0 .. 0.9]
const vec2  SHIFT     = vec2(0.3183, 0.2071); // moves the strongest lines of the
                                         // pattern off the seams (any value works)
const float MIRROR_U  = 0.0;   // 1 = fold u
const float MIRROR_V  = 0.0;   // 1 = fold v (Klein bottle, Moebius band)

vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 raw = fragCoord / iResolution.xy;
    vec2 uv = seamFold(raw) + SHIFT;
    uv.x += iTime * DRIFT;
    uv.y *= TILES_V;

    int n = 1 << BITS;
    vec2 p = uv * float(n);
    ivec2 c = ivec2(floor(p)) & (n - 1);
    int a = c.x & c.y;

    // highest set bit of a = size class of the hole (-1 on the gasket);
    // the lower set bits are the smaller holes nested inside it
    int level = -1;
    int setBits = 0;
    for (int b = 0; b < BITS; b++) {
        if (((a >> b) & 1) != 0) { level = b; setBits++; }
    }

    vec2 fw = min(fwidth(raw), fwidth(fract(raw + 0.5))) * float(n);
    float px = max(fw.x, fw.y);

    vec3 col;
    if (level < 0) {
        col = u_col1;
    } else {
        float k = float(level) / float(BITS - 1);             // 0 small .. 1 big
        vec3 spectrum = 0.5 + 0.5 * cos(TAU * (0.75 * k + vec3(0.0, 0.33, 0.67)));
        vec3 tone = mix(mix(u_col1, u_col2, 0.35 + 0.6 * k), spectrum * mix(vec3(1.0), u_col1, 0.3), RAINBOW);
        float wave = 0.5 + 0.5 * sin(TAU * (iTime * WAVE) - float(level) * 0.9);
        tone *= 0.45 + 0.75 * wave * (1.0 - 0.5 * k);
        // nested sub-holes: each extra set bit darkens one more step
        float nested = level > 0 ? float(setBits - 1) / float(level) : 0.0;
        tone *= 1.0 - NESTING * nested;
        // the gasket of the lower bits, redrawn inside every hole
        if (setBits == 1) tone = mix(tone, u_col1, 0.5);
        // soft rim inside each hole: brighter near the gasket lines
        vec2 f = fract(p);
        vec2 ed = min(f, 1.0 - f);
        float rim = 1.0 - smoothstep(0.0, max(1.5 * px, 0.25), min(ed.x, ed.y));
        col = tone * (1.0 - 0.25 * rim * (1.0 - smoothstep(0.2, 0.45, px)));
    }

    // cells smaller than a pixel: blend toward the average instead of moire
    col = mix(col, mix(u_col1, u_col2, 0.55) * 0.8, smoothstep(0.7, 2.0, px));
    fragColor = vec4(col, 1.0);
}
